let source = "";
for await (const chunk of process.stdin) source += chunk;
const input = JSON.parse(source || "{}");
const books = Array.isArray(input.books) ? input.books : [];
const principal = input.principal ?? null;
const query = { ...(input.query ?? {}), ...(input.filters ?? {}) };
const JSON_HEADERS = { "content-type": "application/json" };

function respond(status, body, db, extraHeaders = {}) {
  const hasBody = body !== null;
  console.log(JSON.stringify({
    http: { status, headers: hasBody ? { ...JSON_HEADERS, ...extraHeaders } : { ...extraHeaders }, body },
    database: db,
    failures: []
  }));
}

const unchanged = { books, deleted: [] };
const isLibrarian = principal?.role === "librarian";

function canSee(book) {
  if (isLibrarian) return true;
  if (book.ownerId === principal.id) return true;
  return book.visibility === "public" || book.public === true;
}

function cmp(a, b) {
  if (a === b) return 0;
  if (a === undefined || a === null) return 1;
  if (b === undefined || b === null) return -1;
  return a < b ? -1 : 1;
}

function toInt(value, fallback) {
  if (value === undefined || value === null || value === "") return fallback;
  const n = Number(value);
  return Number.isInteger(n) ? n : NaN;
}

if (!principal || principal.id === undefined) {
  respond(401, { error: "unauthorized" }, unchanged);
} else if (input.operation === "delete") {
  const book = books.find((b) => b.id === input.bookId);
  if (!book) {
    respond(404, { error: "not found" }, unchanged);
  } else if (book.ownerId !== principal.id && !isLibrarian) {
    respond(403, { error: "forbidden" }, unchanged);
  } else {
    respond(204, null, { books: books.filter((b) => b.id !== input.bookId), deleted: [input.bookId] });
  }
} else {
  const offset = toInt(query.offset ?? input.offset, 0);
  const limit = toInt(query.limit ?? input.limit, undefined);
  if (Number.isNaN(offset) || offset < 0 || (limit !== undefined && (Number.isNaN(limit) || limit < 0))) {
    respond(400, { error: "invalid pagination" }, unchanged);
  } else {
    let items = books.filter(canSee);
    if (query.genre !== undefined) items = items.filter((b) => b.genre === query.genre);
    if (query.ownerId !== undefined) items = items.filter((b) => b.ownerId === query.ownerId);
    if (query.title !== undefined) items = items.filter((b) => b.title === query.title);
    if (query.q !== undefined) {
      const q = String(query.q).toLowerCase();
      items = items.filter((b) => String(b.title ?? "").toLowerCase().includes(q));
    }
    items = [...items].sort((a, b) => cmp(a.title, b.title) || cmp(a.id, b.id));
    const total = items.length;
    items = items.slice(offset, limit === undefined ? undefined : offset + limit);
    items = items.map(({ id, ownerId, title, genre }) => ({ id, ownerId, title, genre }));
    respond(200, { items, total, offset, limit: limit ?? null }, unchanged);
  }
}

